events = get_day_calendar_events(day="2024-05-15")

lunch_event = None

# Try to find lunch with Sarah by name in title/description
for event in events:
    if "Sarah" in event.title or "Sarah" in event.description:
        lunch_event = event

# If not found, try by keyword "Lunch"
if lunch_event is None:
    for event in events:
        if "Lunch" in event.title:
            lunch_event = event

# If still not found, try to find Sarah in contacts and check participants
if lunch_event is None:
    contacts = search_contacts_by_name("Sarah")
    sarah_email = None
    if contacts:
        sarah_email = contacts[0].email

    if sarah_email:
        for event in events:
            if sarah_email in event.participants:
                lunch_event = event

# Now find the meeting before lunch
meeting_before_lunch = None
latest_end_time = None

for event in events:
    # Skip the lunch event itself
    if lunch_event is not None and event.id_ == lunch_event.id_:
        pass
    else:
        # Check if event ends before lunch starts
        if lunch_event is not None and event.end_time < lunch_event.start_time:
            if latest_end_time is None or event.end_time > latest_end_time:
                meeting_before_lunch = event
                latest_end_time = event.end_time

if meeting_before_lunch and lunch_event:
    diff = lunch_event.start_time - meeting_before_lunch.end_time
    total_seconds = diff.total_seconds()
    hours = int(total_seconds // 3600)
    minutes = int((total_seconds % 3600) // 60)
    print(f"{hours:02d}:{minutes:02d}")
else:
    print("Could not find the specific meeting or lunch event.")
